636					<form id="contact-form">
637						<fieldset>
638							<legend class="form-hint">Contact Information</legend>
639							<div class="field">
640								<label for="email">Email <span aria-hidden="true">*</span></label>
641								<input type="email" id="email" name="email" autocomplete="email" inputmode="email" spellcheck="false" autocapitalize="none" required aria-describedby="email-help email-error">
642								<span id="email-error" class="error-message" aria-live="polite"></span>
643								<small id="email-help" class="form-hint">For example, name@example.com</small>
644							</div>
